        assertThat(view.itemField.getValue()).isEmpty();
        assertThat(view.itemField.isInvalid()).isFalse();
        assertThat(view.itemList.getChildren().count()).isEqualTo(1);
        assertThat(itemText(view, 0)).isEqualTo("Apple");
    }

